-- Migration 033: imports. Run after 032. Safe to re-run (replaces what it loaded before).
--  1. Production logs from Farm Data OHR 2026 (Fertigation, Foliar, Inputs, Actions): 301 logs.
--  2. Nursery mother inventory from WebbNursery_2027 (Greenhouse Data, SU26_Gen1 = G1 for the 2027 season): 248 lots, with their cut batches.
set client_min_messages = warning;

-- ---------- 1. Production logs ----------
alter table ops_logs disable trigger ops_logs_audit;
delete from ops_logs where notes like '[import FarmData2026]%';
alter table ops_logs enable trigger ops_logs_audit;

on conflict (name) do nothing;

-- ---------- 2. Nursery: G1 mother lots (SU26_Gen1) on the greenhouse benches ----------
alter table nursery_mothers disable trigger nursery_mothers_audit;
alter table nursery_batches disable trigger nursery_batches_audit;
delete from nursery_mothers where notes like '[import Webb2027]%';
delete from nursery_batches where notes like '[import Webb2027]%';

-- G2 batches cut from the G1 lot of the same strain
update nursery_batches b set mother_id = m.id from nursery_mothers m
 where b.gen = 2 and b.notes like '[import Webb2027]%' and m.gen = 1 and m.notes like '[import Webb2027]%' and lower(m.strain) = lower(b.strain) and b.mother_id is null;

alter table nursery_mothers enable trigger nursery_mothers_audit;
alter table nursery_batches enable trigger nursery_batches_audit;

select (select count(*) from ops_logs where notes like '[import FarmData2026]%') as production_logs,
       (select count(*) from nursery_mothers where notes like '[import Webb2027]%') as g1_lots,
       (select coalesce(sum(qty), 0) from nursery_mothers where notes like '[import Webb2027]%') as g1_moms;
